#include "umicom/editor/intelligence_workbench/code_action_session_model.h"
int main(void){UmiEditorIntelCodeActionSessionModel session;if(umi_editor_intel_code_action_session_model_begin(&session,"session-1")!=UMI_STATUS_OK)return 1;if(umi_editor_intel_code_action_session_model_set_ready(&session,3U)!=UMI_STATUS_OK)return 2;if(!umi_editor_intel_code_action_session_model_valid(&session)||session.item_count!=3U)return 3;if(umi_editor_intel_code_action_session_model_cancel(&session)!=UMI_STATUS_OK||session.phase!=UMI_EDITOR_INTEL_PHASE_CANCELLED)return 4;return 0;}
